class HashMap:
    def __init__(self, m=8):
        self.b = [[] for _ in range(m)]
    def _i(self, k):
        return hash(k) % len(self.b)
    def set(self, k, v):
        i = self._i(k)
        for p in self.b[i]:
            if p[0] == k:
                p[1] = v
                return
        self.b[i].append([k, v])
    def get(self, k):
        for p in self.b[self._i(k)]:
            if p[0] == k:
                return p[1]

def lower_bound(a, x):
    lo, hi = 0, len(a)
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo

from functools import cache

@cache
def fib(n: int) -> int:
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)
